import fs from 'node:fs'; import assert from 'node:assert/strict'; import {spawn} from 'node:child_process'; import {createServer} from 'node:net';
import {createPublicClient,http,parseAbi,keccak256,decodeErrorResult} from 'viem'; import {resolveFoundry} from './contracts/script/native-tool.mjs';
const artifact=JSON.parse(fs.readFileSync('contracts/out/TradingSessionGuard.sol/TradingSessionGuard.json')); const data=fs.readFileSync('evidence/HO-hsk-mainnet-1/initcode.hex','utf8').trim();const preview=JSON.parse(fs.readFileSync('evidence/HO-hsk-mainnet-1/deploy-preview-unsigned-20261027.json')).constructorPreview;
const reserver=createServer();await new Promise(r=>reserver.listen(0,'127.0.0.1',r));const port=reserver.address().port;await new Promise(r=>reserver.close(r));
const rpc=`http://127.0.0.1:${port}`;const command=[resolveFoundry('anvil'),'--host','127.0.0.1','--port',String(port),'--chain-id','31337','--fork-url','https://mainnet.hsk.xyz','--fork-block-number','29372120','--silent'];
const anvil=spawn(command[0],command.slice(1),{stdio:['ignore','ignore','pipe']});let stderr='';anvil.stderr.on('data',d=>stderr+=d.toString());
const report={schemaVersion:'hsk-pristine-paused-smoke/1',startedAt:new Date().toISOString(),sourceSha:'1f1a48d56df96fc6f838d0696f1b5e3500bcf004',sourceDataMode:'MAINNET_READONLY',executionDataMode:'FORK',executionKind:'FORK_TX',sourceChainId:177,executionChainId:31337,forkBlock:'29372120',forkBlockHash:'0x6a111c40dbe323e24bd193cf32411f6ea648e0356d6cffca0b7dad56295c3e73',initcodeKeccak256:keccak256(data),command,checks:[],mainnetTransactionHash:null,limitations:['Local unlocked synthetic sender, NOT actual TEST account readiness or funding.','Same proposed owner and exact initcode; local chain31337 EIP712 domain, not chain177 deployed code.','No key reads, no Guard funding/allowances/session/trade; only one LOCAL creation.']};
const client=createPublicClient({transport:http(rpc,{retryCount:0,timeout:20000})});
try{
 let ready=false;for(let n=0;n<120;n++){if(anvil.exitCode!==null)throw Error('Anvil exited: '+stderr);try{if(await client.getChainId()===31337){ready=true;break;}}catch{}await new Promise(r=>setTimeout(r,100));}assert(ready,'Own local fork failed to start');
 const source=await client.getBlock({blockNumber:29372120n});assert.equal(source.hash,report.forkBlockHash);
 const [sender]=await client.request({method:'eth_accounts'});assert.notEqual(sender.toLowerCase(),preview.initialOwner.toLowerCase()); report.localSender=sender;
 assert.equal(await client.getChainId(),31337); const hash=await client.request({method:'eth_sendTransaction',params:[{from:sender,data,value:'0x0',gas:'0x4c4b40'}]}); const receipt=await client.waitForTransactionReceipt({hash});assert.equal(receipt.status,'success'); const guard=receipt.contractAddress; assert(guard);report.localCreation={hash,address:guard,blockNumber:receipt.blockNumber.toString(),gasUsed:receipt.gasUsed.toString(),status:receipt.status};
 const read=(name,args=[])=>client.readContract({address:guard,abi:artifact.abi,functionName:name,args});
 const record=async(name,expected,args=[])=>{const actual=await read(name,args);if(typeof expected==='string')assert.equal(String(actual).toLowerCase(),expected.toLowerCase(),name);else assert.equal(actual,expected,name);report.checks.push({name,actual:typeof actual==='bigint'?String(actual):actual});};
 const zero='0x0000000000000000000000000000000000000000';const z32='0x'+'00'.repeat(32);
 await record('owner',preview.initialOwner); await record('pendingOwner',zero);await record('status',0);
 for(const name of ['sessionId','intentNonce','allocatedQuoteRaw','allocatedRiskRaw','sessionGrossBuyQuoteRaw','lastTradeAt','lastExitAt'])await record(name,0n);await record('policyVersion',0);
 for(const [name,expected] of [['riskToken',preview.risk],['quoteToken',preview.quote],['router',preview.fixedRouter],['factory',preview.fixedFactory],['pool',preview.fixedPool]])await record(name,expected);
 await record('poolFee',3000); await record('riskDecimals',18);await record('quoteDecimals',6);
 const block=await client.getBlock();await record('utcDayGrossBuyQuoteRaw',0n,[block.timestamp/86400n]);
 const policy=await read('policy');assert.equal(policy[0],0);assert.equal(policy[3],zero);assert.equal(policy[4],zero);assert.equal(policy[5],z32);assert(policy.every(x=>typeof x==='string'?/^0x0+$/.test(x):BigInt(x)===0n));report.checks.push({name:'entire fresh policy zero; roles unset; BOUNDED_EXECUTION default',status:'PASS'});
 const erc20=parseAbi(['function balanceOf(address) view returns (uint256)','function allowance(address,address) view returns (uint256)']);
 for(const token of [preview.risk,preview.quote])for(const [name,args]of [['balanceOf',[guard]],['allowance',[guard,preview.fixedRouter]]]){const actual=await client.readContract({address:token,abi:erc20,functionName:name,args});assert.equal(actual,0n);report.checks.push({name:token+'.'+name,actual:String(actual)});}
 assert.equal(await client.getBalance({address:guard}),0n);report.checks.push({name:'Guard native balance',actual:'0'});
 const runtime=await client.getCode({address:guard});const mask=hex=>{const b=Buffer.from(hex.slice(2),'hex');for(const refs of Object.values(artifact.deployedBytecode.immutableReferences))for(const {start,length}of refs)b.fill(0,start,start+length);return b.toString('hex');};assert.equal(mask(runtime),mask(artifact.deployedBytecode.object));report.checks.push({name:'immutable-masked runtime structure',status:'PASS',runtimeKeccak256:keccak256(runtime)});
 const domain=await read('eip712Domain');assert.equal(domain[1],'HSKPilotGuard');assert.equal(domain[2],'1');assert.equal(domain[3],31337n);assert.equal(domain[4].toLowerCase(),guard.toLowerCase());report.checks.push({name:'EIP712 execution context',chainId:'31337',verifyingContract:guard});
 const intent={sessionId:0n,policyVersion:0,strategyPolicyHash:z32,intentNonce:0n,direction:0,amountInRaw:1n,referenceAmountOutRaw:1n,amountOutMinimumRaw:1n,quoteObservedAt:block.timestamp,quoteBlockNumber:block.number,quoteBlockHash:block.hash,deadline:block.timestamp+1n,evidenceHash:z32};let errorName=null;
 try{await client.simulateContract({account:sender,address:guard,abi:artifact.abi,functionName:'execute',args:[intent,'0x','0x']});}catch(e){let current=e;while(current){if(current.data?.errorName){errorName=current.data.errorName;break;}current=current.cause;}}assert.equal(errorName,'InvalidState');report.checks.push({name:'fresh PAUSED execute eth_call',revert:'InvalidState',transactionHash:null});
 report.status='PASS_PRISTINE_PAUSED_FIXED_BLOCK_FORK_NOT_MAINNET_READY';
}catch(e){report.status='FAIL';report.error=String(e);throw e;}finally{report.finishedAt=new Date().toISOString();fs.writeFileSync('evidence/HO-hsk-mainnet-1/paused-fork-smoke.json',JSON.stringify(report,(_,v)=>typeof v==='bigint'?v.toString():v,2)+'\n');if(anvil.exitCode===null){const stopped=new Promise(r=>anvil.once('exit',r));anvil.kill('SIGTERM');await stopped;}}
console.log(JSON.stringify(report,null,2));

